I’ve been using this wrapper which works as a temporary workaround. This doesn’t work if you remove the `jit` and only handles batch sharding.

```python
@partial(jax.jit, static_argnames=("is_causal", "scale"))
def flash_attention(q, k, v, *, is_causal=False, scale=None):
    def attn(q, k, v):
        return jax.nn.dot_product_attention(
            q, k, v, implementation="cudnn", is_causal=is_causal, scale=scale
        )

    sharding = jax.typeof(q).sharding
    if sharding.spec[0] is None:
        return attn(q, k, v)

    spec = P(sharding.spec[0])
    return jax.shard_map(
        attn,
        mesh=sharding.mesh,
        in_specs=(spec,) * 3,
        out_specs=spec,
        check_vma=False,
    )(q, k, v)
```

